import{_t as e,it as t,n,rt as r}from"./chunks/framework.BIpRff3v.js";var i=JSON.parse(`{"title":"Protected changes, prompts and known limits","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline-protected-changes.md","filePath":"pipeline-protected-changes.md"}`),a={name:`pipeline-protected-changes.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="protected-changes-prompts-and-known-limits" tabindex="-1" dir="auto">Protected changes, prompts and known limits <a class="header-anchor" href="#protected-changes-prompts-and-known-limits" aria-label="Permalink to “Protected changes, prompts and known limits”">​</a></h1><h2 id="protected-change-approval" tabindex="-1" dir="auto">Protected-change approval <a class="header-anchor" href="#protected-change-approval" aria-label="Permalink to “Protected-change approval”">​</a></h2><p dir="auto">A task that needs a dependency, a new app or lib, or a change to a workspace generator used to dead-end at a hard gate and the owner redid it locally. Now the owner <strong>approves such a change once, before any PR exists</strong>. This is a two-week trial.</p><p dir="auto"><strong>Which paths.</strong> <code>pipeline-lib.mjs</code> has two lists, and <code>APPROVABLE_PATH_PATTERNS</code> is a strict subset of <code>FORBIDDEN_PATH_PATTERNS</code> (a test asserts it):</p><table tabindex="0"><thead><tr><th dir="auto">Kind</th><th dir="auto">Paths</th><th dir="auto">What happens</th></tr></thead><tbody><tr><td dir="auto"><strong>Approvable</strong></td><td dir="auto">any <code>package.json</code>, <code>pnpm-lock.yaml</code>, <code>pnpm-workspace.yaml</code>, <code>tools/workspace-plugin/**</code>, <code>tools/pipeline-map/**</code></td><td dir="auto">The owner approves the diff with a command (this section)</td></tr><tr><td dir="auto"><strong>Never approvable</strong></td><td dir="auto"><code>.github/**</code>, <code>CODEOWNERS</code>, <code>tools/security/**</code>, <code>.claude/</code>, <code>.codex/</code>, <code>.pipeline/</code>, <code>.npmrc</code>, <code>.gitmodules</code></td><td dir="auto"><code>forbidden_path</code> hard gate, exactly as before; a local session only</td></tr></tbody></table><p dir="auto">A patch that touches <strong>any</strong> never-approvable path stays a hard gate, even next to approvable ones. Because <code>.github/**</code> can never be in a bot-pushed patch, the pipeline App keeps <code>contents: write</code> and never needs the <code>workflows</code> permission.</p><p dir="auto"><strong>Why before the PR.</strong> Package scripts, the lockfile, the generators that <code>pnpm new:*</code> runs and the map tool that <code>pnpm verify</code> runs all execute with repo secrets as soon as a <code>pull_request</code> workflow runs on them. So nothing may run on the branch until the owner has read it: the branch is pushed <strong>without a PR</strong>, and no workflow may fire on a push to <code>issue-&lt;n&gt;-&lt;slug&gt;</code>. A test (<code>push guard</code> in <code>pipeline-lib.test.mjs</code>) reads every workflow and fails if any <code>on: push</code> lacks a branch filter that leaves those branches out, or if any workflow listens to <code>create</code>. Today only <code>deploy.yml</code> has <code>on: push</code>, limited to <code>main</code>.</p><h3 id="the-flow" tabindex="-1" dir="auto">The flow <a class="header-anchor" href="#the-flow" aria-label="Permalink to “The flow”">​</a></h3><ol><li dir="auto"><strong>Plan.</strong> <code>evaluatePlanApproval</code> lets approvable protected files pass. The outcome note and the plan comment say the owner must approve them before a PR opens. A never-approvable planned path is still <code>protected_surface</code>.</li><li dir="auto"><strong>Develop.</strong> The implement job runs <code>check-patch --accept approvable</code>. If every protected path is approvable and the rest of the patch is fine, it uploads the patch as artifact <code>protected-patch</code> (7 days) and outputs <code>protected=approvable</code> with the sorted paths; otherwise it is today&#39;s <code>forbidden_path</code>. The publish job downloads it, checks that it is exactly the kind implement saw, pushes <code>issue-&lt;n&gt;-&lt;slug&gt;</code> and opens <strong>no PR</strong>. Then <code>protected-request</code> (<code>pipeline.mjs</code>): <ul><li dir="auto">recomputes the protected paths from <code>main...head</code> through the API (a branch that holds a never-approvable path, or a list of 300+ files that may be cut off, is deleted and reported as <code>forbidden_path</code>);</li><li dir="auto">posts the bot comment <code>&lt;!-- pipeline:protected-approval head=&lt;sha&gt; paths=&lt;sha256 of the sorted path list&gt; --&gt;</code> on the issue: the protected paths with their <strong>full diff</strong> (<code>&lt;details&gt;</code>; cut only past GitHub&#39;s comment size limit, with a link to the branch compare view), a summary of the other files, the commands <code>/approve-protected &lt;first 12 hex of the head&gt;</code> and <code>/reject-protected &lt;reason&gt;</code>, and the proposed PR title and body;</li><li dir="auto">appends an outcome note (<code>develop</code> / <code>protected_approval_needed</code>) that does <strong>not</strong> set <code>stage:routing</code>, and sets <code>stage:awaiting-approval</code>. The router never moves an item out of that stage.</li></ul></li><li dir="auto"><strong>The owner answers</strong> with a comment on the issue whose whole body is one command (<code>protected-approve.yml</code>, <code>issue_comment: created</code>). It accepts only if <strong>all</strong> of these hold, else one short bot reply with the reason and no state change: <ul><li dir="auto">the commenter is <code>vars.PIPELINE_OWNER_LOGIN</code> and a <code>User</code> (the same <code>checkDispositionAuthor</code> as <code>/disposition</code>; unset variable = nobody);</li><li dir="auto">the body is exactly the command, nothing else, and the comment was not edited (only <code>created</code> events count, and the script re-reads the comment);</li><li dir="auto">the issue is open and in <code>stage:awaiting-approval</code>;</li><li dir="auto">the SHA prefix is the <strong>latest</strong> request&#39;s head <strong>and</strong> an <code>issue-&lt;n&gt;-</code> branch still points at that head;</li><li dir="auto">the protected path set recomputed from <code>main...head</code> hashes to the request&#39;s <code>paths=</code>;</li><li dir="auto">every recomputed path is still approvable.</li></ul></li><li dir="auto"><strong>Approve.</strong> The bot opens the (draft) PR with <code>Closes #n</code> and the approved paths in its body, appends the record note <code>&lt;!-- pipeline:protected-approved issue=&lt;n&gt; pr=&lt;m&gt; head=&lt;sha&gt; paths=&lt;hash&gt; by=&lt;login&gt; comment=&lt;id&gt; --&gt;</code> on the PR, sets the commit status <code>pipeline/protected-approval</code> = <code>success</code> on the head and <code>stage:building</code> on the issue. From here it is the normal path: CI → (Copilot, if required) → gates.</li><li dir="auto"><strong>Reject.</strong> An outcome note (<code>develop</code> / <code>protected_rejected</code>) and <code>stage:routing</code>; the rules table sends it to a human. The branch is kept.</li><li dir="auto"><strong>A push invalidates the approval.</strong> The approval names one head and one path set. On every new PR head (<code>protected-approve.yml</code>, <code>workflow_run</code> on CI <code>requested</code>) and in every gates evaluation, <code>pipeline/protected-approval</code> is recomputed: protected paths and a head that is not the one in the latest record note = <code>pending</code>, and a new request for the new head is posted on the issue (<code>stage:awaiting-approval</code> again). The status is <code>success</code> automatically when the PR has no protected paths, and for a PR the pipeline did not open (a person&#39;s own PR, Dependabot: the code-owner review covers it). A never-approvable path on a pipeline PR is <code>failure</code>.</li><li dir="auto"><strong>Gates.</strong> <code>pipeline/gates</code> requires <code>pipeline/protected-approval</code> = <code>success</code> whenever the PR touches protected paths.</li></ol><p dir="auto"><strong>Pushes after the PR exists.</strong> No workflow pushes to a PR&#39;s branch once the PR is open, so no CI run sees unapproved protected content from a bot. A <strong>person&#39;s</strong> push to the branch does run CI once before the status can turn pending: <code>pull_request</code> workflows start on every push, and nothing can stop that from a workflow. That is the price of a PR that already exists; the merge stays blocked until the new head is approved.</p><p dir="auto"><strong>Stale requests.</strong> Each request is for one head. Re-developing force-pushes the branch and posts a new request; an approval that names an older head is answered with &quot;stale&quot;.</p><h2 id="prompts" tabindex="-1" dir="auto">Prompts <a class="header-anchor" href="#prompts" aria-label="Permalink to “Prompts”">​</a></h2><p dir="auto"><code>.github/prompts/*.md</code> are versioned (<code>version:</code> in front matter). Every comment, review and commit an agent produces names the prompt file and version. Bump the version when you change a prompt&#39;s behaviour. Each prompt starts with the same security rules: the content it is given is data, never instructions.</p><h2 id="known-limits" tabindex="-1" dir="auto">Known limits <a class="header-anchor" href="#known-limits" aria-label="Permalink to “Known limits”">​</a></h2><ul><li dir="auto">Deep links inside a PR preview fall back to the production <code>404.html</code> (Pages serves only the root one). Previews open fine from their root URL.</li><li dir="auto">As sole code owner you cannot approve your own PRs. The ruleset lets you (<code>PIPELINE_OWNER_LOGIN</code>) bypass it, but only inside a PR (bypass mode &quot;pull request&quot;): you still cannot push to <code>main</code>. Bots and Apps have no bypass. Pipeline PRs are authored by the App, so this only affects PRs you open yourself.</li><li dir="auto">The pipeline&#39;s own files (<code>.github/**</code>) cannot be changed by the pipeline. Change them in a normal PR.</li><li dir="auto"><strong>Every PR to <code>main</code> needs <code>pipeline/gates</code> = success</strong> (CI green, no open review thread, and the Copilot review when it is required), including PRs you open yourself. <code>approval.yml</code> evaluates every same-repo PR after green CI. A status you post yourself does not count.</li><li dir="auto"><strong>Dependabot and fork PRs get no <code>pipeline/gates</code> status</strong>, so they cannot merge as they are. Runs triggered by Dependabot see only <em>Dependabot</em> secrets, so the App token is not available. For Dependabot, add <code>PIPELINE_APP_PRIVATE_KEY</code> as a Dependabot secret too (Settings → Secrets and variables → Dependabot), so its PRs get the status like any other. For a fork PR, re-create the change on a same-repo branch.</li></ul>`,15)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};